@php($v=fn($key,$default='')=>old($key,$item?->{$key}??$default))<label class="field">Nombre en español<input name="label" required value="{{$v('label')}}"></label><label class="field">Nombre en inglés<input name="label_en" value="{{$v('label_en')}}"></label><label class="field">Tipo de destino<select name="target_type" class="target-type"><option value="route" @selected($v('target_type','route')==='route')>Página existente del sistema</option><option value="page" @selected($v('target_type')==='page')>Página creada aquí</option><option value="url" @selected($v('target_type')==='url')>URL externa</option></select></label><label class="field">Destino<select name="target" class="target-select"><optgroup label="Páginas del sistema">@foreach(['about'=>'Quiénes somos','routes.index'=>'Rutas y pasajes','companies.index'=>'Empresas','discover.index'=>'Descubrir','travels.index'=>'Buscar pasaje','home'=>'Inicio'] as $route=>$name)<option value="{{$route}}" @selected($v('target')===$route)>{{$name}}</option>@endforeach</optgroup><optgroup label="Páginas personalizadas">@foreach($pages as $p)<option value="{{$p->slug}}" @selected($v('target')===$p->slug)>{{$p->title}}</option>@endforeach</optgroup></select><input name="external_target" style="display:none" placeholder="https://..." value="{{$v('target')}}"></label><label class="field">Orden<input type="number" name="position" min="0" max="999" value="{{$v('position',10)}}"></label><div class="checks"><label><input type="hidden" name="is_active" value="0"><input type="checkbox" name="is_active" value="1" @checked($v('is_active',true))> Visible</label><label><input type="hidden" name="opens_new_tab" value="0"><input type="checkbox" name="opens_new_tab" value="1" @checked($v('opens_new_tab'))> Nueva pestaña</label></div><script>document.currentScript.closest('form').querySelector('.target-type').addEventListener('change',function(){const f=this.closest('form'),s=f.querySelector('.target-select'),i=f.querySelector('[name=external_target]');if(this.value==='url'){i.style.display='block';i.name='target';s.name='';}else{i.style.display='none';i.name='external_target';s.name='target';}});document.currentScript.closest('form').querySelector('.target-type').dispatchEvent(new Event('change'));</script>
